-- 00_indexes.sql — indexes, policies and constraints the clone's own setup
-- scripts author for the newer tables. The PostgREST catalog exposes no index
-- information, so these are replayed from bluebellschool/src/api/*.sql and pruned
-- to statements that can only add: CREATE INDEX / POLICY / CONSTRAINT, COMMENT,
-- ENABLE ROW LEVEL SECURITY. Anything destructive or column-altering is
-- dropped from the bundle (01_schema.sql already carries every live column).
-- The surviving statements are executed through bb_try(), which reports and
-- skips failures, so it can be re-run freely. Every statement here needs
-- its table to exist first, so paste it after 01_schema.sql and 02_rls.sql.
-- Generated by tools/gen-schema.mjs — do not hand-edit; re-run the tool.

set search_path = public;

-- ---- guarded execution ----
bb_try() runs one statement and only reports a failure, so the order
these files are pasted in never matters and a re-run is harmless.
create or replace function bb_try(p_sql text) returns void language plpgsql as $fn$
begin
  execute p_sql;
exception when others then
  raise notice 'bluebell 00_indexes: skipped % (%)', left(p_sql, 70), sqlerrm;
end
$fn$;

