-- >>>>>>>>>> db/04_seed_bluebell.sql
-- 04_seed_bluebell.sql — Bluebell's first settings row, so the public site and
-- the admin portals come up populated the moment this bundle is pasted.
-- Generated by tools/gen-schema.mjs — do not hand-edit; re-run the tool.
-- Scalar values come from the "settings" block of tools/site-content.json; a
-- missing one is emitted as BLUEBELL_*_PLACEHOLDER. Images point at /site/*.jpg
-- which ships inside the app (public/site), so nothing has to be uploaded.

set search_path = public;

insert into bluebell_settings (schoolname, session, term, "cbtPassword", "adminEmail", additionalemails, "nextTermBegins", "nextTermFees", "schoolOpened", "checkResult", "lockResult", "resultLock", use_class_specific_fees, "heroContent", "facilitiesContent", "galleryContent", "testimonialContent", "aboutContent", "contactContent")
select 'Bluebell International School', 'BLUEBELL_SESSION_PLACEHOLDER', 'BLUEBELL_TERM_PLACEHOLDER', 'BLUEBELL_CBT_PASSWORD_PLACEHOLDER', 'BLUEBELL_ADMIN_EMAIL_PLACEHOLDER', '', 'BLUEBELL_NEXT_TERM_BEGINS_PLACEHOLDER', 'BLUEBELL_NEXT_TERM_FEES_PLACEHOLDER', 'BLUEBELL_SCHOOL_OPENED_PLACEHOLDER', 'BLUEBELL_CHECK_RESULT_PLACEHOLDER', 'false', 'false', 'true', '[{"image":"/site/hero-classroom.jpg","heading":"Wisdom, Integrity, Courage","content":"A values-driven international education where every child from Crèche to Secondary is known by name and taught to think clearly, act honestly and stand brave."},{"image":"/site/hero-outdoor.jpg","heading":"Room to grow, room to play","content":"Safe grounds, guided play and daily outdoor learning build strong bodies, steady hands and confident characters."},{"image":"/site/hero-library.jpg","heading":"Readers for life","content":"Our library and guided reading programme give every pupil the fluency and imagination that all later learning rests on."}]'::jsonb, '[{"image":"/site/facility-workroom.jpg","heading":"Early years classroom","content":"Ordered shelves of hands-on learning materials where our youngest pupils build concentration, coordination and independence."},{"image":"/site/facility-library.jpg","heading":"Library and reading room","content":"A quiet, well-stocked reading corner with age-appropriate books and guided reading sessions every week."},{"image":"/site/facility-playground.jpg","heading":"Playground","content":"Soft-surfaced play equipment, sand pit and open grass for physical play, games and outdoor lessons."},{"image":"/site/facility-art.jpg","heading":"Art and music room","content":"Easels, paints, drums and keyboards - a room where creativity is treated as serious learning."},{"image":"/site/facility-ict.jpg","heading":"Computer laboratory","content":"A full ICT room where pupils build keyboard confidence and practise CBT skills before examinations."}]'::jsonb, '[{"image":"/site/gallery-classroom.jpg","content":"Guided one-to-one teaching"},{"image":"/site/gallery-reading.jpg","content":"Shared reading in the library"},{"image":"/site/gallery-maths.jpg","content":"Maths with concrete manipulatives"},{"image":"/site/gallery-art.jpg","content":"Art lesson"},{"image":"/site/gallery-sports.jpg","content":"Sports day"},{"image":"/site/gallery-music.jpg","content":"Music and rhythm class"},{"image":"/site/gallery-science.jpg","content":"Hands-on science"},{"image":"/site/gallery-graduation.jpg","content":"Kindergarten graduation"},{"image":"/site/about-welcome.jpg","content":"Our school environment"}]'::jsonb, '[{"image":"/site/portrait-parent.jpg","text":"My daughter came to Bluebell shy and unsure of the alphabet. A term later she reads to her younger brother at home. The teachers really do know each child individually."},{"image":"/site/portrait-teacher.jpg","text":"We are given the materials, the small classes and the time to teach properly. That is why the children here progress so quickly and love coming to school."},{"image":"/site/portrait-pupil.jpg","text":"I like the library and the computer room best. My teacher helps me when I am stuck, and I got 1st in my class last term."}]'::jsonb, '{"text":"Bluebell International School exists to give every child a first-class foundation: literacy and numeracy taught properly, character formed deliberately around our motto Wisdom, Integrity and Courage, and curiosity protected in a warm, orderly, well-resourced environment.","text2":"We receive every child as a gift and teach them as though we knew it. Our promise to parents is simple: your child will be safe, known, and taught to the very best of our ability from their first day in our early years class to their last in Secondary.","details":[{"heading":"Every child known","content":"Small classes and one-to-one teaching time, so no child is left behind and none is left idle."},{"heading":"Literacy and numeracy first","content":"Systematic phonics and concrete maths before abstraction - the two skills every later subject depends on."},{"heading":"Character by design","content":"Wisdom, integrity and courage are taught on purpose every day, not left to chance."}]}'::jsonb, '{"address":"BLUEBELL_ADDRESS_PLACEHOLDER","phone":"BLUEBELL_PHONE_PLACEHOLDER","email":"BLUEBELL_EMAIL_PLACEHOLDER"}'::jsonb
where not exists (select 1 from bluebell_settings);

-- Backfill for projects where an earlier version of this seed already ran:
-- fills only columns that are still NULL, so values edited through the admin
-- Setting page are never overwritten.
update bluebell_settings set
  "adminEmail" = coalesce("adminEmail", 'BLUEBELL_ADMIN_EMAIL_PLACEHOLDER'),
  additionalemails = coalesce(additionalemails, ''),
  "nextTermBegins" = coalesce("nextTermBegins", 'BLUEBELL_NEXT_TERM_BEGINS_PLACEHOLDER'),
  "nextTermFees" = coalesce("nextTermFees", 'BLUEBELL_NEXT_TERM_FEES_PLACEHOLDER'),
  "schoolOpened" = coalesce("schoolOpened", 'BLUEBELL_SCHOOL_OPENED_PLACEHOLDER'),
  "checkResult" = coalesce("checkResult", 'BLUEBELL_CHECK_RESULT_PLACEHOLDER'::date),
  "lockResult" = coalesce("lockResult", false),
  "resultLock" = coalesce("resultLock", false),
  use_class_specific_fees = coalesce(use_class_specific_fees, true);

-- The first administrator. Supabase Auth owns the password; this row is what
-- the portals read to grant the admin role (src/utils/authUtils.js). Create the
-- Auth accounts with: node tools/create-auth-users.mjs --apply
-- BLUEBELL_ADMIN_EMAIL_PLACEHOLDER is still a placeholder — set settings.adminEmail
-- in tools/site-content.json or update this row afterwards.

insert into bluebell_userauth (email)
select 'BLUEBELL_ADMIN_EMAIL_PLACEHOLDER'
where not exists (select 1 from bluebell_userauth);

-- Done.

